import { useIconColor } from '@advui/icons'
import { Text, View, type ViewProps } from 'tamagui'
import {
  type CircularProgressSize,
  type CircularProgressTone,
  progressFraction,
  ring,
  toneColor,
  valueFontSize,
} from './geometry'

export interface CircularProgressProps extends Omit<ViewProps, 'children'> {
  /** Current value. Omit (or `null`) for a spinning, indeterminate ring. */
  value?: number | null
  max?: number
  /** `sm` 24px · `md` 40px · `lg` 64px. */
  size?: CircularProgressSize
  tone?: CircularProgressTone
  /** Accessible name, e.g. "Storage used". */
  label?: string
  /** Show the percentage in the middle (`md` and `lg`). */
  showValue?: boolean
}

/**
 * A ring that fills as a task completes, for tight spaces and dashboards.
 * Web: an SVG circle; the indeterminate ring spins with the spinner keyframes
 * in GlobalStyles.
 */
export function CircularProgress({
  value = null,
  max = 100,
  size = 'md',
  tone = 'primary',
  label,
  showValue = false,
  ...props
}: CircularProgressProps) {
  const { clamped, fraction } = progressFraction(value, max)
  const geometry = ring(size, fraction)
  const indicator = useIconColor(toneColor[tone])
  const track = useIconColor('$muted')
  const fontSize = valueFontSize[size]

  return (
    <View
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={clamped ?? undefined}
      aria-busy={fraction === null || undefined}
      width={geometry.diameter}
      height={geometry.diameter}
      alignItems="center"
      justifyContent="center"
      {...props}
    >
      <svg
        className={fraction === null ? 'aui-spinner' : undefined}
        width={geometry.diameter}
        height={geometry.diameter}
        viewBox={`0 0 ${geometry.diameter} ${geometry.diameter}`}
        fill="none"
        aria-hidden
        // Start the ring at 12 o'clock.
        style={{ display: 'block', transform: fraction === null ? undefined : 'rotate(-90deg)' }}
      >
        <circle
          cx={geometry.center}
          cy={geometry.center}
          r={geometry.radius}
          stroke={track}
          strokeWidth={geometry.stroke}
        />
        {geometry.visible ? (
          <circle
            cx={geometry.center}
            cy={geometry.center}
            r={geometry.radius}
            stroke={indicator}
            strokeWidth={geometry.stroke}
            strokeLinecap="round"
            strokeDasharray={geometry.circumference}
            strokeDashoffset={geometry.offset}
            style={{ transition: 'stroke-dashoffset 300ms ease-out' }}
          />
        ) : null}
      </svg>
      {showValue && fontSize && fraction !== null ? (
        <Text
          aria-hidden
          position="absolute"
          fontFamily="$body"
          fontSize={fontSize}
          lineHeight={fontSize}
          fontWeight="600"
          color="$foreground"
        >
          {Math.round(fraction * 100)}%
        </Text>
      ) : null}
    </View>
  )
}

import { useIconColor } from '@advui/icons'
import { useEffect, useRef } from 'react'
import { Animated, Easing } from 'react-native'
import Svg, { Circle } from 'react-native-svg'
import { Text, View } from 'tamagui'
import { useReducedMotion } from '../../hooks/useReducedMotion'
import type { CircularProgressProps } from './CircularProgress'
import { progressFraction, ring, toneColor, valueFontSize } from './geometry'

// One turn, like the web spinner keyframes; slower when motion is reduced, as
// a loading indicator still has to show it is busy.
const TURN_MS = 800
const REDUCED_TURN_MS = 1600

/** Native: react-native-svg, with an Animated rotation for the indeterminate ring. */
export function CircularProgress({
  value = null,
  max = 100,
  size = 'md',
  tone = 'primary',
  label,
  showValue = false,
  ...props
}: CircularProgressProps) {
  const { clamped, fraction } = progressFraction(value, max)
  const geometry = ring(size, fraction)
  const indicator = useIconColor(toneColor[tone])
  const track = useIconColor('$muted')
  const fontSize = valueFontSize[size]
  const reducedMotion = useReducedMotion()
  const spin = useRef(new Animated.Value(0)).current
  const spinning = fraction === null

  useEffect(() => {
    if (!spinning) return
    const loop = Animated.loop(
      Animated.timing(spin, {
        toValue: 1,
        duration: reducedMotion ? REDUCED_TURN_MS : TURN_MS,
        easing: Easing.linear,
        useNativeDriver: true,
      }),
    )
    loop.start()
    return () => {
      loop.stop()
      spin.setValue(0)
    }
  }, [spin, spinning, reducedMotion])

  const rotate = spinning
    ? spin.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '360deg'] })
    : // Start the ring at 12 o'clock.
      '-90deg'

  return (
    <View
      accessible
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={clamped ?? undefined}
      aria-busy={spinning || undefined}
      width={geometry.diameter}
      height={geometry.diameter}
      alignItems="center"
      justifyContent="center"
      {...props}
    >
      <Animated.View style={{ transform: [{ rotate }] }}>
        <Svg
          width={geometry.diameter}
          height={geometry.diameter}
          viewBox={`0 0 ${geometry.diameter} ${geometry.diameter}`}
          fill="none"
          importantForAccessibility="no-hide-descendants"
        >
          <Circle
            cx={geometry.center}
            cy={geometry.center}
            r={geometry.radius}
            stroke={track}
            strokeWidth={geometry.stroke}
          />
          {geometry.visible ? (
            <Circle
              cx={geometry.center}
              cy={geometry.center}
              r={geometry.radius}
              stroke={indicator}
              strokeWidth={geometry.stroke}
              strokeLinecap="round"
              strokeDasharray={geometry.circumference}
              strokeDashoffset={geometry.offset}
            />
          ) : null}
        </Svg>
      </Animated.View>
      {showValue && fontSize && fraction !== null ? (
        <Text
          aria-hidden
          position="absolute"
          fontFamily="$body"
          fontSize={fontSize}
          lineHeight={fontSize}
          fontWeight="600"
          color="$foreground"
        >
          {Math.round(fraction * 100)}%
        </Text>
      ) : null}
    </View>
  )
}

export type { CircularProgressProps }

/** Diameter and stroke in px per size, shared by the web and native renderers. */
export const circularSizes = {
  sm: { diameter: 24, stroke: 3 },
  md: { diameter: 40, stroke: 4 },
  lg: { diameter: 64, stroke: 6 },
} as const

export type CircularProgressSize = keyof typeof circularSizes
export type CircularProgressTone = 'primary' | 'success' | 'warning' | 'error'

export const toneColor = {
  primary: '$primary',
  success: '$success',
  warning: '$warning',
  error: '$error',
} as const satisfies Record<CircularProgressTone, `$${string}`>

// The percentage label is only legible from `md` up.
export const valueFontSize = { sm: null, md: '$1', lg: '$3' } as const

/** The share of the ring an indeterminate indicator covers while it spins. */
const INDETERMINATE_FRACTION = 0.25

/**
 * Circle geometry for a ring of `size`: its radius, circumference and the
 * dash offset that shows `fraction` (0–1) of it, or a spinning quarter when
 * `fraction` is null.
 */
export function ring(size: CircularProgressSize, fraction: number | null) {
  const { diameter, stroke } = circularSizes[size]
  const radius = (diameter - stroke) / 2
  const circumference = 2 * Math.PI * radius
  const shown = fraction ?? INDETERMINATE_FRACTION
  return {
    diameter,
    stroke,
    center: diameter / 2,
    radius,
    circumference,
    offset: circumference * (1 - shown),
    visible: shown > 0,
  }
}

/** The value clamped to 0…max, as a fraction, or null when indeterminate. */
export function progressFraction(value: number | null, max: number) {
  if (value === null) return { clamped: null, fraction: null }
  const clamped = Math.min(max, Math.max(0, value))
  return { clamped, fraction: max > 0 ? clamped / max : 0 }
}

